 85→// ParseHookInput parses Gemini CLI hook input from stdin.
 86→func (g *GeminiCLIAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
 87→	data, err := io.ReadAll(reader)
 88→	if err != nil {
 89→		return nil, fmt.Errorf("failed to read input: %w", err)
 90→	}
 91→
 92→	if len(data) == 0 {
 93→		return nil, errors.New("empty input")
 94→	}
 95→
 96→	input := &agent.HookInput{
 97→		HookType:  hookType,
 98→		Timestamp: time.Now(),
 99→		RawData:   make(map[string]interface{}),
100→	}
101→
102→	// Parse based on hook type
103→	switch hookType {
104→	case agent.HookSessionStart, agent.HookSessionEnd, agent.HookStop:
105→		var raw sessionInfoRaw
106→		if err := json.Unmarshal(data, &raw); err != nil {
107→			return nil, fmt.Errorf("failed to parse session info: %w", err)
108→		}
109→		input.SessionID = raw.SessionID
110→		input.SessionRef = raw.TranscriptPath
111→		// Store Gemini-specific fields in RawData
112→		input.RawData["cwd"] = raw.Cwd
113→		input.RawData["hook_event_name"] = raw.HookEventName
114→		if raw.Source != "" {
115→			input.RawData["source"] = raw.Source
116→		}
117→		if raw.Reason != "" {
118→			input.RawData["reason"] = raw.Reason
119→		}
120→
121→	case agent.HookUserPromptSubmit:
122→		// BeforeAgent is Gemini's equivalent to Claude's UserPromptSubmit
123→		// It provides the user's prompt in the "prompt" field
124→		var raw agentHookInputRaw
125→		if err := json.Unmarshal(data, &raw); err != nil {
126→			return nil, fmt.Errorf("failed to parse agent hook input: %w", err)
127→		}
128→		input.SessionID = raw.SessionID
129→		input.SessionRef = raw.TranscriptPath
130→		input.RawData["cwd"] = raw.Cwd
131→		input.RawData["hook_event_name"] = raw.HookEventName
132→		if raw.Prompt != "" {
133→			input.UserPrompt = raw.Prompt
134→			input.RawData["prompt"] = raw.Prompt
135→		}
136→
137→	case agent.HookPreToolUse, agent.HookPostToolUse:
138→		var raw toolHookInputRaw
139→		if err := json.Unmarshal(data, &raw); err != nil {
140→			return nil, fmt.Errorf("failed to parse tool hook input: %w", err)
141→		}
142→		input.SessionID = raw.SessionID
143→		input.SessionRef = raw.TranscriptPath
144→		input.ToolName = raw.ToolName
145→		input.ToolInput = raw.ToolInput
146→		if hookType == agent.HookPostToolUse {
147→			input.ToolResponse = raw.ToolResponse
148→		}
149→		input.RawData["cwd"] = raw.Cwd
150→		input.RawData["hook_event_name"] = raw.HookEventName
151→	}
152→
153→	return input, nil
154→}
