164→// ResolveSessionFile returns the path to a Gemini session file.
165→// Gemini names files as session-<date>-<shortid>.json where shortid is the first 8 chars
166→// of the session UUID. This searches for an existing file matching the pattern, falling
167→// back to <dir>/<id>.json if no match is found.
168→func (g *GeminiCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
169→	// Try to find existing file matching Gemini's naming convention:
170→	// session-*-<first8chars>.json
171→	shortID := agentSessionID
172→	if len(shortID) > 8 {
173→		shortID = shortID[:8]
174→	}
175→
176→	pattern := filepath.Join(sessionDir, "session-*-"+shortID+".json")
177→	matches, err := filepath.Glob(pattern)
178→	if err == nil && len(matches) > 0 {
179→		// Return the most recent match (last alphabetically, since date is in the name)
180→		return matches[len(matches)-1]
181→	}
182→
183→	// Fallback: construct a default path
184→	return filepath.Join(sessionDir, agentSessionID+".json")
185→}
