187→// GetSessionDir returns the directory where Gemini stores session transcripts.
188→// Gemini stores sessions in ~/.gemini/tmp/<project-hash>/chats/
189→func (g *GeminiCLIAgent) GetSessionDir(repoPath string) (string, error) {
190→	// Check for test environment override
191→	if override := os.Getenv("ENTIRE_TEST_GEMINI_PROJECT_DIR"); override != "" {
192→		return override, nil
193→	}
194→
195→	homeDir, err := os.UserHomeDir()
196→	if err != nil {
197→		return "", fmt.Errorf("failed to get home directory: %w", err)
198→	}
199→
200→	// Gemini uses a hash of the project path for the directory name
201→	projectDir := SanitizePathForGemini(repoPath)
202→	return filepath.Join(homeDir, ".gemini", "tmp", projectDir, "chats"), nil
203→}
