205→// ReadSession reads a session from Gemini's storage (JSON transcript file).
206→// The session data is stored in NativeData as raw JSON bytes.
207→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
208→	if input.SessionRef == "" {
209→		return nil, errors.New("session reference (transcript path) is required")
210→	}
211→
212→	// Read the raw JSON file
213→	data, err := os.ReadFile(input.SessionRef)
214→	if err != nil {
215→		return nil, fmt.Errorf("failed to read transcript: %w", err)
216→	}
217→
218→	// Parse to extract computed fields
219→	modifiedFiles, err := ExtractModifiedFiles(data)
220→	if err != nil {
221→		// Non-fatal: we can still return the session without modified files
222→		modifiedFiles = nil
223→	}
224→
225→	return &agent.AgentSession{
226→		SessionID:     input.SessionID,
227→		AgentName:     g.Name(),
228→		SessionRef:    input.SessionRef,
229→		StartTime:     time.Now(),
230→		NativeData:    data,
231→		ModifiedFiles: modifiedFiles,
232→	}, nil
233→}
234→
235→// WriteSession writes a session to Gemini's storage (JSON transcript file).
236→// Uses the NativeData field which contains raw JSON bytes.
237→func (g *GeminiCLIAgent) WriteSession(session *agent.AgentSession) error {
238→	if session == nil {
239→		return errors.New("session is nil")
240→	}
241→
242→	// Verify this session belongs to Gemini CLI
243→	if session.AgentName != "" && session.AgentName != g.Name() {
244→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
245→	}
246→
247→	if session.SessionRef == "" {
248→		return errors.New("session reference (transcript path) is required")
249→	}
250→
251→	if len(session.NativeData) == 0 {
252→		return errors.New("session has no native data to write")
253→	}
254→
255→	// Write the raw JSON data
256→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
257→		return fmt.Errorf("failed to write transcript: %w", err)
258→	}
259→
260→	return nil
261→}
