268→// SanitizePathForGemini converts a path to Gemini's project directory format.
269→// Gemini uses a hash-like sanitization similar to Claude.
270→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
271→
272→func SanitizePathForGemini(path string) string {
273→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
274→}
