276→// TranscriptAnalyzer interface implementation
277→
278→// GetTranscriptPosition returns the current message count of a Gemini transcript.
279→// Gemini uses JSON format with a messages array, so position is the message count.
280→// Returns 0 if the file doesn't exist or is empty.
281→func (g *GeminiCLIAgent) GetTranscriptPosition(path string) (int, error) {
282→	if path == "" {
283→		return 0, nil
284→	}
285→
286→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
287→	if err != nil {
288→		if os.IsNotExist(err) {
289→			return 0, nil
290→		}
291→		return 0, fmt.Errorf("failed to read transcript: %w", err)
292→	}
293→
294→	if len(data) == 0 {
295→		return 0, nil
296→	}
297→
298→	transcript, err := ParseTranscript(data)
299→	if err != nil {
300→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
301→	}
302→
303→	return len(transcript.Messages), nil
304→}
305→
306→// ExtractModifiedFilesFromOffset extracts files modified since a given message index.
307→// For Gemini (JSON format), offset is the starting message index.
308→// Returns:
309→//   - files: list of file paths modified by Gemini (from Write/Edit tools)
310→//   - currentPosition: total number of messages in the transcript
311→//   - error: any error encountered during reading
312→func (g *GeminiCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
313→	if path == "" {
314→		return nil, 0, nil
315→	}
316→
317→	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
318→	if readErr != nil {
319→		if os.IsNotExist(readErr) {
320→			return nil, 0, nil
321→		}
322→		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
323→	}
324→
325→	if len(data) == 0 {
326→		return nil, 0, nil
327→	}
328→
329→	transcript, parseErr := ParseTranscript(data)
330→	if parseErr != nil {
331→		return nil, 0, parseErr
332→	}
333→
334→	totalMessages := len(transcript.Messages)
335→
336→	// Extract files from messages starting at startOffset
337→	fileSet := make(map[string]bool)
338→	for i := startOffset; i < len(transcript.Messages); i++ {
339→		msg := transcript.Messages[i]
340→		// Only process gemini messages (assistant messages)
341→		if msg.Type != MessageTypeGemini {
342→			continue
343→		}
344→
345→		// Process tool calls in this message
346→		for _, toolCall := range msg.ToolCalls {
347→			// Check if it's a file modification tool
348→			isModifyTool := false
349→			for _, name := range FileModificationTools {
350→				if toolCall.Name == name {
351→					isModifyTool = true
352→					break
353→				}
354→			}
355→
356→			if !isModifyTool {
357→				continue
358→			}
359→
360→			// Extract file path from args map
361→			var file string
362→			if fp, ok := toolCall.Args["file_path"].(string); ok && fp != "" {
363→				file = fp
364→			} else if p, ok := toolCall.Args["path"].(string); ok && p != "" {
365→				file = p
366→			} else if fn, ok := toolCall.Args["filename"].(string); ok && fn != "" {
367→				file = fn
368→			}
369→
370→			if file != "" && !fileSet[file] {
371→				fileSet[file] = true
372→				files = append(files, file)
373→			}
374→		}
375→	}
376→
377→	return files, totalMessages, nil
378→}
379→
380→// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
381→// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
382→// the messages array while preserving the JSON structure in each chunk.
383→func (g *GeminiCLIAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
384→	var transcript GeminiTranscript
385→	if err := json.Unmarshal(content, &transcript); err != nil {
386→		// Fall back to JSONL chunking if not valid Gemini JSON
387→		chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
388→		if chunkErr != nil {
389→			return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
390→		}
391→		return chunks, nil
392→	}
393→
394→	if len(transcript.Messages) == 0 {
395→		return [][]byte{content}, nil
396→	}
397→
398→	var chunks [][]byte
399→	var currentMessages []GeminiMessage
400→	currentSize := len(`{"messages":[]}`) // Base JSON structure size
401→
402→	for i, msg := range transcript.Messages {
403→		// Marshal message to get its size
404→		msgBytes, err := json.Marshal(msg)
405→		if err != nil {
406→			logging.Warn(context.Background(), "failed to marshal Gemini message during chunking",
407→				slog.Int("message_index", i),
408→				slog.String("error", err.Error()),
409→			)
410→			continue
411→		}
412→		msgSize := len(msgBytes) + 1 // +1 for comma separator
413→
414→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
415→			// Save current chunk
416→			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
417→			if err != nil {
418→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
419→			}
420→			chunks = append(chunks, chunkData)
421→
422→			// Start new chunk
423→			currentMessages = nil
424→			currentSize = len(`{"messages":[]}`)
425→		}
426→
427→		currentMessages = append(currentMessages, msg)
428→		currentSize += msgSize
429→	}
430→
431→	// Add the last chunk
432→	if len(currentMessages) > 0 {
433→		chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
434→		if err != nil {
435→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
436→		}
437→		chunks = append(chunks, chunkData)
438→	}
439→
440→	// Ensure we created at least one chunk (could be empty if all messages failed to marshal)
441→	if len(chunks) == 0 {
442→		return nil, errors.New("failed to create any chunks: all messages failed to marshal")
443→	}
444→
445→	return chunks, nil
446→}
447→
448→// ReassembleTranscript merges Gemini JSON chunks by combining their message arrays.
449→func (g *GeminiCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
450→	var allMessages []GeminiMessage
451→
452→	for _, chunk := range chunks {
453→		var transcript GeminiTranscript
454→		if err := json.Unmarshal(chunk, &transcript); err != nil {
455→			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
456→		}
457→		allMessages = append(allMessages, transcript.Messages...)
458→	}
459→
460→	result, err := json.Marshal(GeminiTranscript{Messages: allMessages})
461→	if err != nil {
462→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
463→	}
464→	return result, nil
465→}
