500→func readGeminiSettings(t *testing.T, tempDir string) GeminiSettings {
501→	t.Helper()
502→	settingsPath := filepath.Join(tempDir, ".gemini", "settings.json")
503→	data, err := os.ReadFile(settingsPath)
504→	if err != nil {
505→		t.Fatalf("failed to read settings.json: %v", err)
506→	}
507→
508→	var settings GeminiSettings
509→	if err := json.Unmarshal(data, &settings); err != nil {
510→		t.Fatalf("failed to parse settings.json: %v", err)
511→	}
512→	return settings
513→}
