515→func writeGeminiSettings(t *testing.T, tempDir, content string) {
516→	t.Helper()
517→	geminiDir := filepath.Join(tempDir, ".gemini")
518→	if err := os.MkdirAll(geminiDir, 0o755); err != nil {
519→		t.Fatalf("failed to create .gemini dir: %v", err)
520→	}
