package copilot

import "encoding/json"

// CopilotHookConfig represents the .github/hooks/copilot-setup.json structure
type CopilotHookConfig struct {
	Version int                           `json:"version"`
	Hooks   map[string][]CopilotHookEntry `json:"hooks"`
}

// CopilotHookEntry represents a single hook command entry
type CopilotHookEntry struct {
	Type       string `json:"type"`
	Bash       string `json:"bash"`
	TimeoutSec int    `json:"timeoutSec,omitempty"`
}

// hookBase contains common fields present in all Copilot hook stdin JSON.
// All hooks include sessionId, transcript_path, cwd, hookEventName, and timestamp.
type hookBase struct {
	SessionID      string `json:"sessionId"`
	TranscriptPath string `json:"transcript_path"`
	Cwd            string `json:"cwd"`
	HookEventName  string `json:"hookEventName"`
	Timestamp      string `json:"timestamp"`
}

// sessionStartRaw is the stdin JSON for the sessionStart hook
type sessionStartRaw struct {
	hookBase
	Source        string `json:"source,omitempty"`
	InitialPrompt string `json:"initialPrompt,omitempty"`
}

// sessionEndRaw is the stdin JSON for the sessionEnd hook
type sessionEndRaw struct {
	hookBase
	Reason string `json:"reason,omitempty"`
}

// userPromptRaw is the stdin JSON for the userPromptSubmitted hook
type userPromptRaw struct {
	hookBase
	Prompt string `json:"prompt,omitempty"`
}

// agentStopRaw is the stdin JSON for the agentStop hook
type agentStopRaw struct {
	hookBase
}

// subagentStopRaw is the stdin JSON for the subagentStop hook
type subagentStopRaw struct {
	hookBase
}

// toolUseRaw is the stdin JSON for preToolUse/postToolUse hooks
type toolUseRaw struct {
	hookBase
	ToolName   string          `json:"toolName"`
	ToolArgs   json.RawMessage `json:"toolArgs,omitempty"`
	ToolResult json.RawMessage `json:"toolResult,omitempty"`
}

// errorRaw is the stdin JSON for the errorOccurred hook
type errorRaw struct {
	hookBase
	Error json.RawMessage `json:"error,omitempty"`
}

// Tool names used in GitHub Copilot that modify files
const (
	ToolEdit   = "edit"
	ToolCreate = "create"
)

// FileModificationTools lists tools that create or modify files in GitHub Copilot
var FileModificationTools = []string{
	ToolEdit,
	ToolCreate,
}

// Package copilot implements the Agent interface for GitHub Copilot CLI.
package copilot

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCopilot, NewCopilotAgent)
}

// CopilotAgent implements the Agent interface for GitHub Copilot CLI.
type CopilotAgent struct{}

// NewCopilotAgent creates a new CopilotAgent.
func NewCopilotAgent() agent.Agent {
	return &CopilotAgent{}
}

// Name returns the agent registry key.
func (c *CopilotAgent) Name() agent.AgentName {
	return agent.AgentNameCopilot
}

// Type returns the agent type identifier.
func (c *CopilotAgent) Type() agent.AgentType {
	return agent.AgentTypeCopilot
}

// Description returns a human-readable description.
func (c *CopilotAgent) Description() string {
	return "GitHub Copilot - GitHub's AI coding assistant"
}

// IsPreview returns true as the Copilot integration is in preview.
func (c *CopilotAgent) IsPreview() bool { return true }

// DetectPresence checks if GitHub Copilot is configured in the repository.
func (c *CopilotAgent) DetectPresence() (bool, error) {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "."
	}

	// Check if our hooks are installed
	if c.AreHooksInstalled() {
		return true, nil
	}

	// Check for .github/hooks directory with copilot config
	configPath := filepath.Join(repoRoot, ".github", "hooks", CopilotConfigFileName)
	if _, err := os.Stat(configPath); err == nil {
		return true, nil
	}

	return false, nil
}

// GetHookConfigPath returns the path to Copilot's hook config file.
func (c *CopilotAgent) GetHookConfigPath() string {
	return filepath.Join(".github", "hooks", CopilotConfigFileName)
}

// SupportsHooks returns true as GitHub Copilot supports lifecycle hooks.
func (c *CopilotAgent) SupportsHooks() bool {
	return true
}

// ParseHookInput parses Copilot hook input from stdin.
func (c *CopilotAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, fmt.Errorf("failed to read input: %w", err)
	}

	if len(data) == 0 {
		return nil, errors.New("empty input")
	}

	input := &agent.HookInput{
		HookType:  hookType,
		Timestamp: time.Now(),
		RawData:   make(map[string]interface{}),
	}

	switch hookType {
	case agent.HookSessionStart, agent.HookSessionEnd, agent.HookStop:
		var raw hookBase
		if err := json.Unmarshal(data, &raw); err != nil {
			return nil, fmt.Errorf("failed to parse hook input: %w", err)
		}
		input.SessionID = raw.SessionID
		input.SessionRef = raw.TranscriptPath
		input.RawData["cwd"] = raw.Cwd
		input.RawData["hookEventName"] = raw.HookEventName

	case agent.HookUserPromptSubmit:
		var raw userPromptRaw
		if err := json.Unmarshal(data, &raw); err != nil {
			return nil, fmt.Errorf("failed to parse hook input: %w", err)
		}
		input.SessionID = raw.SessionID
		input.SessionRef = raw.TranscriptPath
		input.RawData["cwd"] = raw.Cwd
		input.RawData["hookEventName"] = raw.HookEventName
		if raw.Prompt != "" {
			input.UserPrompt = raw.Prompt
			input.RawData["prompt"] = raw.Prompt
		}

	case agent.HookPreToolUse, agent.HookPostToolUse:
		var raw toolUseRaw
		if err := json.Unmarshal(data, &raw); err != nil {
			return nil, fmt.Errorf("failed to parse tool hook input: %w", err)
		}
		input.SessionID = raw.SessionID
		input.SessionRef = raw.TranscriptPath
		input.ToolName = raw.ToolName
		input.ToolInput = raw.ToolArgs
		if hookType == agent.HookPostToolUse {
			input.ToolResponse = raw.ToolResult
		}
		input.RawData["cwd"] = raw.Cwd
		input.RawData["hookEventName"] = raw.HookEventName
	}

	return input, nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CopilotAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// ProtectedDirs returns directories that Copilot uses.
// .github is a shared directory (not solely ours), so we don't protect it.
func (c *CopilotAgent) ProtectedDirs() []string { return []string{} }

// GetSessionDir returns the directory where Copilot stores session transcripts.
func (c *CopilotAgent) GetSessionDir(_ string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	return filepath.Join(homeDir, ".copilot", "session-state"), nil
}

// ResolveSessionFile returns the path to a Copilot session file.
func (c *CopilotAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID, "events.jsonl")
}

// ReadSession reads a session from Copilot's storage.
func (c *CopilotAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // Reading from controlled transcript path
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  c.Name(),
		SessionRef: input.SessionRef,
		StartTime:  time.Now(),
		NativeData: data,
	}, nil
}

// WriteSession writes a session to Copilot's storage.
func (c *CopilotAgent) WriteSession(session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns the command to resume a Copilot session.
func (c *CopilotAgent) FormatResumeCommand(_ string) string {
	return "copilot --resume"
}

package copilot

import (
	"fmt"
	"io"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time interface assertions
var _ agent.TranscriptAnalyzer = (*CopilotAgent)(nil)

// HookNames returns the hook verbs Copilot supports.
func (c *CopilotAgent) HookNames() []string {
	return c.GetHookNames()
}

// ParseHookEvent translates a Copilot hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
func (c *CopilotAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return c.parseSessionStart(stdin)
	case HookNameUserPromptSubmitted:
		return c.parseTurnStart(stdin)
	case HookNameAgentStop:
		return c.parseTurnEnd(stdin)
	case HookNameSessionEnd:
		return c.parseSessionEnd(stdin)
	case HookNameSubagentStop:
		return c.parseSubagentEnd(stdin)
	case HookNamePreToolUse, HookNamePostToolUse, HookNameErrorOccurred:
		return nil, nil //nolint:nilnil // nil event = no lifecycle action
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CopilotAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSONL transcript into chunks.
func (c *CopilotAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
	return agent.ChunkJSONL(content, maxSize)
}

// ReassembleTranscript combines JSONL chunks back into a single transcript.
func (c *CopilotAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks)
}

// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
func (c *CopilotAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return ExtractPromptsFromData(data, fromOffset)
}

// ExtractSummary extracts the last assistant message as a session summary.
func (c *CopilotAgent) ExtractSummary(sessionRef string) (string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return "", fmt.Errorf("failed to read transcript: %w", err)
	}
	return ExtractLastAssistantMessage(data), nil
}

// GetTranscriptPosition returns the current line count of the JSONL transcript.
func (c *CopilotAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}

	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("failed to read transcript: %w", err)
	}

	return CountLines(data), nil
}

// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
func (c *CopilotAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
	if path == "" {
		return nil, 0, nil
	}

	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
	if readErr != nil {
		if os.IsNotExist(readErr) {
			return nil, 0, nil
		}
		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
	}

	if len(data) == 0 {
		return nil, 0, nil
	}

	totalLines := CountLines(data)
	extractedFiles := ExtractModifiedFilesFromLines(data, startOffset)

	return extractedFiles, totalLines, nil
}

// --- Internal hook parsing functions ---

func (c *CopilotAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CopilotAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[userPromptRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Prompt:     raw.Prompt,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CopilotAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[agentStopRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CopilotAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionEndRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CopilotAgent) parseSubagentEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentStopRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SubagentEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

