package copilot

import (
	"bytes"
	"encoding/json"
	"strings"
)

// Copilot JSONL transcript parsing.
// Copilot transcripts use JSONL format (one JSON object per line).
// The exact event schema will be refined when actual transcript samples are available.

// transcriptEvent represents a single event in a Copilot JSONL transcript.
// Events may contain role, type, content, and tool call information.
type transcriptEvent struct {
	Role     string          `json:"role,omitempty"`
	Type     string          `json:"type,omitempty"`
	Content  string          `json:"content,omitempty"`
	ToolName string          `json:"toolName,omitempty"`
	ToolArgs json.RawMessage `json:"toolArgs,omitempty"`
}

// CountLines counts the number of non-empty lines in JSONL content.
func CountLines(data []byte) int {
	if len(data) == 0 {
		return 0
	}

	count := 0
	lines := bytes.Split(data, []byte("\n"))
	for _, line := range lines {
		if len(bytes.TrimSpace(line)) > 0 {
			count++
		}
	}
	return count
}

// ExtractModifiedFilesFromLines extracts file paths modified by tool calls
// from JSONL lines starting at the given offset.
func ExtractModifiedFilesFromLines(data []byte, startOffset int) []string {
	lines := bytes.Split(data, []byte("\n"))
	fileSet := make(map[string]bool)
	var files []string

	lineIndex := 0
	for _, line := range lines {
		trimmed := bytes.TrimSpace(line)
		if len(trimmed) == 0 {
			continue
		}

		if lineIndex < startOffset {
			lineIndex++
			continue
		}
		lineIndex++

		var event transcriptEvent
		if err := json.Unmarshal(trimmed, &event); err != nil {
			continue
		}

		// Check if this is a file modification tool call
		if !isFileModificationTool(event.ToolName) {
			continue
		}

		file := extractFilePath(event.ToolArgs)
		if file != "" && !fileSet[file] {
			fileSet[file] = true
			files = append(files, file)
		}
	}

	return files
}

// ExtractPromptsFromData extracts user prompts from JSONL data starting at the given line offset.
func ExtractPromptsFromData(data []byte, fromOffset int) ([]string, error) {
	lines := bytes.Split(data, []byte("\n"))
	var prompts []string

	lineIndex := 0
	for _, line := range lines {
		trimmed := bytes.TrimSpace(line)
		if len(trimmed) == 0 {
			continue
		}

		if lineIndex < fromOffset {
			lineIndex++
			continue
		}
		lineIndex++

		var event transcriptEvent
		if err := json.Unmarshal(trimmed, &event); err != nil {
			continue
		}

		if event.Role == "user" && event.Content != "" {
			prompts = append(prompts, event.Content)
		}
	}

	return prompts, nil
}

// ExtractLastAssistantMessage extracts the last assistant message from JSONL data.
func ExtractLastAssistantMessage(data []byte) string {
	lines := bytes.Split(data, []byte("\n"))

	for i := len(lines) - 1; i >= 0; i-- {
		trimmed := bytes.TrimSpace(lines[i])
		if len(trimmed) == 0 {
			continue
		}

		var event transcriptEvent
		if err := json.Unmarshal(trimmed, &event); err != nil {
			continue
		}

		if event.Role == "assistant" && event.Content != "" {
			return event.Content
		}
	}

	return ""
}

// isFileModificationTool checks if a tool name modifies files.
func isFileModificationTool(toolName string) bool {
	for _, name := range FileModificationTools {
		if toolName == name {
			return true
		}
	}
	return false
}

// extractFilePath extracts a file path from tool args JSON.
// Checks common field names: file_path, path, filePath, filename.
func extractFilePath(args json.RawMessage) string {
	if len(args) == 0 {
		return ""
	}

	var argsMap map[string]interface{}
	if err := json.Unmarshal(args, &argsMap); err != nil {
		return ""
	}

	// Try common path field names
	for _, key := range []string{"file_path", "path", "filePath", "filename"} {
		if v, ok := argsMap[key]; ok {
			if s, ok := v.(string); ok && s != "" {
				return s
			}
		}
	}

	return ""
}

// SliceFromLine returns JSONL data scoped to lines starting from startLine.
// Returns the original data if startLine <= 0.
// Returns nil if startLine exceeds the number of lines.
func SliceFromLine(data []byte, startLine int) []byte {
	if len(data) == 0 || startLine <= 0 {
		return data
	}

	lines := bytes.Split(data, []byte("\n"))
	lineIndex := 0
	var result [][]byte

	for _, line := range lines {
		trimmed := bytes.TrimSpace(line)
		if len(trimmed) == 0 {
			continue
		}

		if lineIndex >= startLine {
			result = append(result, line)
		}
		lineIndex++
	}

	if len(result) == 0 {
		return nil
	}

	return []byte(strings.Join(byteSlicesToStrings(result), "\n"))
}

// byteSlicesToStrings converts [][]byte to []string.
func byteSlicesToStrings(slices [][]byte) []string {
	result := make([]string, len(slices))
	for i, s := range slices {
		result[i] = string(s)
	}
	return result
}

