func TestCountLines(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		input    string
		expected int
	}{
		{"empty", "", 0},
		{"single line", `{"type":"session.start"}`, 1},
		{"two lines", "line1\nline2", 2},
		{"trailing newline", "line1\nline2\n", 2},
		{"blank lines ignored", "line1\n\n\nline2\n", 2},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := CountLines([]byte(tc.input))
			if got != tc.expected {
				t.Errorf("CountLines() = %d, want %d", got, tc.expected)
			}
		})
	}
}

