{"type":"tool.execution_start","data":{"toolCallId":"tc2","toolName":"edit","arguments":{"file_path":"/tmp/other.go","old_string":"foo","new_string":"bar"}},"id":"e8","timestamp":"2025-06-19T18:25:04.001Z","parentId":"e7"}
