172→// buildCondensedTranscriptFromCopilot parses a Copilot events.jsonl transcript
173→// and extracts a condensed view for summarization.
174→func buildCondensedTranscriptFromCopilot(content []byte) ([]Entry, error) {
175→	events, err := copilot.ParseTranscript(content)
176→	if err != nil {
177→		return nil, fmt.Errorf("failed to parse Copilot transcript: %w", err)
178→	}
179→
180→	var entries []Entry
181→	for _, event := range events {
182→		switch event.Type {
183→		case copilot.EventUserMessage:
184→			var data struct {
185→				Content string `json:"content"`
186→			}
187→			if err := json.Unmarshal(event.Data, &data); err != nil {
188→				continue
189→			}
190→			if data.Content != "" {
191→				entries = append(entries, Entry{
192→					Type:    EntryTypeUser,
193→					Content: data.Content,
194→				})
195→			}
196→
197→		case copilot.EventAssistantMessage:
198→			var data struct {
199→				Content      string `json:"content"`
200→				ToolRequests []struct {
201→					Name      string         `json:"name"`
202→					Arguments map[string]any `json:"arguments"`
203→				} `json:"toolRequests"`
204→			}
205→			if err := json.Unmarshal(event.Data, &data); err != nil {
206→				continue
207→			}
208→			if data.Content != "" {
209→				entries = append(entries, Entry{
210→					Type:    EntryTypeAssistant,
211→					Content: data.Content,
212→				})
213→			}
214→			for _, tc := range data.ToolRequests {
215→				entries = append(entries, Entry{
216→					Type:       EntryTypeTool,
217→					ToolName:   tc.Name,
218→					ToolDetail: extractCopilotToolDetail(tc.Arguments),
219→				})
220→			}
221→		}
222→	}
223→
224→	return entries, nil
225→}
